 editor.hidden=!profileModel||step!==0;profileSave.disabled=!profileModel;localPermissions.hidden=step!==1;profilePanel.querySelector('h3').textContent=profileModel?'Modelo · '+profileModel.split('/').pop():'Nenhum modelo configurado';
 if(!profileDirty){modelRoots=[...(profile.allowed_roots||[])];renderModelRoots();toolsInput.checked=profile.capabilities?.tools===true;for(const [key] of modelPermissionFields)$('profile-permission-'+key).checked=profile.permissions?.[key]===true;refreshPermissionAvailability();binaryInput.value=profile.binary||active?.binary||runtimes.find(r=>r.binary)?.binary||'';for(const [key] of hardwareFields)$('profile-'+key).value=p[key]||'';profileSave.textContent='Salvar perfil deste modelo';}
 const launchChoice=$('local-file').value;$('local-file').replaceChildren(...paths.map(path=>new Option(path.split('/').pop(),path)));if(paths.includes(launchChoice))$('local-file').value=launchChoice;else $('local-file').value=profileModel;
